#include "game/world_generation/caves/cave_formations.h"
#include <iostream>
using namespace altaria::caves;
int main(){PlanSettings cfg;cfg.region_size=512;cfg.floor=-448;cfg.ceiling=320;cfg.infernal_chance=1;cfg.entrance_chance=0;cfg.isolated_chance=0;cfg.archetypes={{"mod:tall",3,3,{80,200,80},{80,200,80},1}};Planner p(1337,0,cfg,[](float,float){return 200.f;});auto n=p.region({0,0});if(!p.valid()||!n.valid||n.chambers.empty())return 2;FormationRule rule;rule.id="judge:pillar";rule.kind=FormationKind::pillar;rule.radius={3,3};rule.height={5,18};auto f=plan_formation(n.chambers.front(),rule,0,8,9);size_t probes=0;auto mask=support_formation(f,[&](int x,int y,int z){probes++;FormationCell c;c.rock=true;c.allowed=true;float d=0;int p[]={x,y,z};for(int a=0;a<3;a++){float q=(p[a]-n.chambers.front().center[a])/n.chambers.front().radius[a];d+=q*q;}c.carved=d<1;return c;});std::cout<<"TALL_VALID_PROFILE planner_valid="<<p.valid()<<" rule_valid="<<valid_formation(rule)<<" pillar_y_extent="<<f.box.hi[1]-f.box.lo[1]<<" mask_y_size="<<mask.size[1]<<" probes="<<probes<<" kept="<<mask.kept<<"\n";return mask.size[1]>256&&probes>0&&mask.kept>0?0:1;}
